from pydantic import BaseModel, StrictInt, StrictStr, Field, ValidationError

class M(BaseModel):
    limit: StrictInt = Field(default=50, ge=1, le=200)
    cursor: StrictStr | None = Field(default=None, min_length=1)

for v in [True, False, 1.0, "2", 0, 201, None, 50]:
    try:
        print(repr(v), "->", M(limit=v).limit)
    except ValidationError:
        print(repr(v), "-> REJECTED")

for c in [123, True, "", " "]:
    try:
        print("cursor", repr(c), "->", M(cursor=c).cursor)
    except ValidationError:
        print("cursor", repr(c), "-> REJECTED")
EOF

